'use strict';
let rateconDBPromise=null,rateconDocs=[],reviewingRatecon=null,rateconURLs=[];
window.activeRateconId=null;
function rateconDB(){if(!rateconDBPromise)rateconDBPromise=new Promise((resolve,reject)=>{if(!window.indexedDB){reject(Error('Document storage is unavailable in this browser.'));return}const r=indexedDB.open('sagisolar-documents',1);r.onupgradeneeded=()=>r.result.createObjectStore('ratecons',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not open document storage.'));r.onblocked=()=>reject(Error('Close other Truckload tabs and retry.'));});return rateconDBPromise;}
async function docOp(mode,action){const db=await rateconDB();return new Promise((resolve,reject)=>{const tx=db.transaction('ratecons',mode),request=action(tx.objectStore('ratecons'));let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(Error('Could not save or read the document. Browser storage may be full.'));tx.onabort=()=>reject(Error('Document storage was interrupted.'));});}
function fileURL(doc){const u=URL.createObjectURL(doc.blob);rateconURLs.push(u);return u;}
function openDocument(doc){if(window.Capacitor?.isNativePlatform()){window.truckloadExport(doc.name,doc.blob).catch(()=>toast('Sharing was cancelled or could not finish. Your original is still saved.'));return;}const a=document.createElement('a');a.href=fileURL(doc);a.target='_blank';a.rel='noopener';a.click();}
window.setActiveRatecon=function(id,name){window.activeRateconId=id;$('activeRateconLabel').textContent=id?`Attached: ${name||rateconDocs.find(d=>d.id===id)?.name||'Rate confirmation'}`:'PDF or photo · attach it to your estimate';$('detachRatecon').hidden=!id;};$('detachRatecon').onclick=()=>window.setActiveRatecon(null);
let readingController=null;
function setReading(active){$('rateconFile').disabled=active;$('cancelRateconRead').hidden=!active;$('retryRateconRead').disabled=active;$('tripForm').querySelector('button[type="submit"]').disabled=active;}
$('cancelRateconRead').onclick=()=>readingController?.abort();
async function readSavedDoc(doc,forceOCR=false){
 const fuelPrice=$('price').value;$('tripForm').reset();$('price').value=fuelPrice;last=null;
 readingController=new AbortController();setReading(true);let updated={...doc};showRatecon({...doc,note:'Reading your document. Fields fill as each page is scanned…'});
 try{const {readDocument}=await import('./document-reader.mjs?v=20261018-3');const r=await readDocument(await doc.blob.arrayBuffer(),doc.type,{signal:readingController.signal,forceOCR,onPage:text=>{updated={...updated,text,fields:RateconCore.suggest(text),note:'Scanning remaining pages… Review these suggestions when reading finishes.'};showRatecon(updated);},onProgress:message=>$('rateconStatus').textContent=message});const fields=RateconCore.suggest(r.text),count=['pay','miles','origin','destination','loadNumber'].filter(k=>fields[k]!==''&&fields[k]!==undefined).length;
 updated={...updated,text:r.text,fields,readStatus:r.text.trim()?'read':'empty',note:(r.text.trim()?`Read ${count} of 5 load fields${r.ocrPages?' using scanning where needed':''}. Verify every suggested value against the original. `:'No readable text found. Try a clearer PDF or photo, or enter details manually. ')+(fields.warnings||[]).join(' ')+' '+r.note};
 }catch(e){updated={...updated,readStatus:'error',note:'Reading did not finish: '+e.message+' You can retry scanning or enter details manually.'};}
 try{showRatecon(updated);calculate();$('rateconStatus').textContent=updated.readStatus==='read'?'Document read. Load details and payment are filled in below. Check the values against the original.':updated.note;$('rateconReview').scrollIntoView({behavior:'smooth',block:'start'});await docOp('readwrite',store=>store.put(updated));await renderRatecons();}catch(e){$('rateconStatus').textContent='Your extracted fields are available below, but saving failed: '+e.message;}finally{readingController=null;setReading(false);}return updated;
}
$('retryRateconRead').onclick=()=>{if(reviewingRatecon&&!readingController)readSavedDoc(reviewingRatecon,true)};
$('rateconFile').onchange=async()=>{const file=$('rateconFile').files[0];if(!file)return;if(file.size>10*1024*1024){$('rateconStatus').textContent='Choose a file no larger than 10 MB.';$('rateconFile').value='';return}$('rateconReview').hidden=true;setReading(true);$('rateconStatus').textContent='Checking and saving your document…';
 try{const all=await docOp('readonly',store=>store.getAll());if(all.reduce((n,d)=>n+d.size,0)+file.size>50*1024*1024)throw Error('This app limits documents to 50 MB on this device. Remove an older document first.');const bytes=await file.arrayBuffer(),type=RateconCore.detectType(new Uint8Array(bytes));if(!type)throw Error('Choose a valid PDF, JPG, PNG or WebP file. Export HEIC photos as JPG or PDF first.');const doc={id:crypto.randomUUID(),name:file.name.slice(0,200),size:file.size,type,blob:new Blob([bytes],{type}),createdAt:new Date().toISOString(),text:'',note:'Document saved. Reading has not completed.',fields:{},readStatus:'pending'};await docOp('readwrite',store=>store.put(doc));await readSavedDoc(doc);
 }catch(e){$('rateconStatus').textContent=e.message;}finally{setReading(false);$('rateconFile').value='';}};
function showRatecon(doc){
 reviewingRatecon=doc;
 for(const k of ['pay','miles','origin','destination','loadNumber','pickupAt','deliveryAt','pickupAddress','deliveryAddress','broker','equipment','weight','notes'])$(k).value=doc.fields[k]??'';
 window.setActiveRatecon(doc.id,doc.name);
 last=null;
 $('loadDetails').open=true;
 $('extractionNote').textContent=doc.note;
 $('rateconText').textContent=doc.text||'No text extracted. View the original document.';
 $('rateconImage').innerHTML=doc.type.startsWith('image/')?`<img src="${fileURL(doc)}" alt="Uploaded rate confirmation for review">`:'';
 $('rateconReview').hidden=false;
 $('openCurrentRatecon').onclick=()=>openDocument(doc);
}
async function renderRatecons(){try{rateconDocs=(await docOp('readonly',s=>s.getAll())).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));$('rateconList').innerHTML=rateconDocs.map(d=>`<article class="trip-card document-item"><h3 class="document-title">${esc(d.name)}</h3><small>${new Date(d.createdAt).toLocaleDateString()} · ${(d.size/1024/1024).toFixed(2)} MB · ${d.type==='application/pdf'?'PDF':'Photo'}${d.fields.loadNumber?' · Load '+esc(d.fields.loadNumber):''}</small><div class="actions"><button data-review="${d.id}">Review & use</button><button data-open="${d.id}">Open original ↗</button><button data-download="${d.id}">Save or share original</button><button class="text-button" data-delete="${d.id}">Remove document</button></div><label>Attach to an existing saved trip<select data-attach="${d.id}"><option value="">Choose a saved trip</option>${saved.map(s=>`<option value="${s.id}">${esc(tripLabel(s))}${s.rateconId===d.id?' · Attached':''}</option>`).join('')}</select></label><small>${saved.filter(s=>s.rateconId===d.id).length} saved trip(s) linked</small></article>`).join('')||'<div class="card">No rate confirmations uploaded yet.</div>';
 for(const b of $('rateconList').querySelectorAll('[data-download]'))b.onclick=()=>{const doc=rateconDocs.find(d=>d.id===b.dataset.download);window.truckloadExport(doc.name,doc.blob).catch(()=>toast('Export was cancelled or could not finish. Your original is still saved.'));};
 for(const b of $('rateconList').querySelectorAll('[data-review]'))b.onclick=async()=>{if(readingController)return;let doc=rateconDocs.find(d=>d.id===b.dataset.review);if(!doc.reviewedAt){if(!doc.text?.trim()){await readSavedDoc(doc);return;}doc={...doc,fields:RateconCore.suggest(doc.text),note:'Details refreshed from the document text. Review every value before applying.'};}showRatecon(doc);calculate();tab('plan');$('uploadPanel').open=true;$('rateconReview').scrollIntoView({behavior:'smooth',block:'start'});};for(const b of $('rateconList').querySelectorAll('[data-open]'))b.onclick=()=>openDocument(rateconDocs.find(d=>d.id===b.dataset.open));
 for(const select of $('rateconList').querySelectorAll('[data-attach]'))select.onchange=()=>{if(!select.value)return;const trip=saved.find(s=>String(s.id)===select.value);if(trip.rateconId&&trip.rateconId!==select.dataset.attach&&!confirm('Replace the document attached to this saved trip?')){select.value='';return}const next=saved.map(s=>String(s.id)===select.value?{...s,rateconId:select.dataset.attach}:s);if(persist('sagi-trips',next)){saved=next;renderRatecons();toast('Rate confirmation attached to saved trip.');}};
 for(const b of $('rateconList').querySelectorAll('[data-delete]'))b.onclick=async()=>{if(!confirm('Remove this document from this browser? Your trip estimates will remain.'))return;const id=b.dataset.delete,next=saved.map(s=>s.rateconId===id?{...s,rateconId:null}:s);if(!persist('sagi-trips',next))return;saved=next;try{await docOp('readwrite',s=>s.delete(id));if(window.activeRateconId===id)window.setActiveRatecon(null);if(reviewingRatecon?.id===id){reviewingRatecon=null;$('rateconReview').hidden=true;}renderRatecons();toast('Document removed.');}catch(e){toast(e.message)}};
 }catch(e){$('rateconList').textContent=e.message;}}
window.renderRatecons=renderRatecons;
const renderSavedWithoutRatecon=renderSaved;
renderSaved=function(){renderSavedWithoutRatecon();renderRatecons();$('savedList').querySelectorAll('.trip-card').forEach((card,i)=>{const trip=saved[i];if(!trip?.rateconId)return;const b=document.createElement('button');b.textContent='Open rate confirmation ↗';b.onclick=async()=>{try{const doc=await docOp('readonly',s=>s.get(trip.rateconId));if(!doc){toast('Document not found on this device. Upload it again.');return}openUploads();showRatecon(doc);$('rateconReview').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){toast(e.message)}};card.querySelector('.actions').prepend(b);});};
window.addEventListener('pagehide',()=>{rateconURLs.forEach(u=>URL.revokeObjectURL(u));rateconURLs=[];});
